const i = $json;
const q = (s, tag) => String(s == null ? '' : (typeof s === 'object' ? JSON.stringify(s) : s)).split(tag).join('');
// Tolère le format d'erreur natif n8n (errorWorkflow) ou l'appel explicite.
const kind = i.kind || (i.execution && 'workflow_error') || 'workflow_error';
const wk = i.workflow_key || (i.workflow && i.workflow.name) || 'unknown';
const error = i.error || (i.execution && i.execution.error && i.execution.error.message) || 'unknown';
const payload = i.payload || {};
const trace = String(i.trace_id || '').match(/^[0-9a-f-]{36}$/i) ? `'${i.trace_id}'::uuid` : 'null';
const sql = [
  `select fn_log_event('error','workflow_error','workflow',null, $wk$${q(wk,'$wk$')}$wk$, null,null,null,'error',null,null,null, ${trace}, jsonb_build_object('error', $er$${q(error,'$er$')}$er$));`,
  `select fn_enqueue_job($k$${q(kind,'$k$')}$k$, $pl$${q(payload,'$pl$')}$pl$::jsonb, 5, 30, $wk$${q(wk,'$wk$')}$wk$, ${trace});`
].join('\n');
return [{ json: { sql } }];
